D.SpellTexts[161662]={Description={["f82d097b5f0b7198:172"]="施法者向附近的敌人喷吐数支闪电箭。每支闪电箭会造成自然伤害，目标离冲击点越远，受到的伤害就越高。\r\n每支闪电箭都会额外弹跳两次。"},Aura={["3e3a226e456b016d:22"]=S[9731]}}
D.SpellTexts[161689]={Description={["6957124e05747fc9:35"]="悲伤地叫着，寻求指引。"},Aura={["ef2218abfefb515c:37"]="这只幼崽迷路了，正在找妈妈。"}}
