D.SpellTexts[161724]={Description={["1679ac4618997bbb:33"]="使玩家与精华之泉调和。"},Aura={["9aa5b86eacd80641:104"]="与精华之泉调和，允许你在不确认的情况下分解物品。离的太远会取消该效果。"}}
D.SpellTexts[161733]={Description={["f7284d6bc71c7b6a:92"]=S[8673]},Aura={["f7284d6bc71c7b6a:92"]=S[8673]}}
D.SpellTexts[161736]={Description={["2315a3db456c84f2:139"]="精华之泉可以将优质或更高品质的武器和护甲分解为附魔材料。物品将被永久摧毁。\r\n\r\n是否继续？"}}
D.SpellTexts[161761]={Description={["38ba389fc5e4d9d4:56"]="丢水桶来熄灭茂林幽谷扭扭周遭的火焰。"}}
