D.SpellTexts[161787]={Description={["0ed30e4a0484a0ed:36"]="学习德拉诺工程学秘术。"}}
D.SpellTexts[161788]={Description={["127c0dde10806a53:35"]="学习德拉诺附魔的奥秘。"}}
