D.SpellTexts[161819]={Description={["0ddfa76f4e64f4ba:162"]="施法者向附近敌人喷吐数支闪电箭。每支闪电箭会分裂成数支更小的闪电箭向前行进，并对沿途击中的所有玩家造成自然伤害。"},Aura={["3e3a226e456b016d:22"]=S[9731]}}
D.SpellTexts[161820]={Description={["7d353fe21f5ee9f1:46"]="对烈焰中的所有敌人造成火焰伤害。"}}
