D.SpellTexts[162104]={Description={["d8c66e04f3876a6d:46"]="在烈焰中每秒造成火焰伤害。"},Aura={["f0d0cee564456b40:29"]="每秒造成火焰伤害。"}}
D.SpellTexts[162106]={Aura={["ce25dafb002e611e:71"]="爆击几率提高5%。\r\n只在赞加拉和古尔达要塞有效。"}}
D.SpellTexts[162111]={Description={["e52431bdac2da8ea:51"]="对施法者前方一条直线上的敌人造成物理伤害。"}}
D.SpellTexts[162112]={Aura={["13b07d90f01a5d0f:63"]="造成的伤害提高10%。每3秒恢复1%的最大生命值。"}}
D.SpellTexts[162116]={Description={["4b57ef6889e5604b:67"]="令逃脱的冷却时间缩短一半。只能在阿什兰使用。"},Aura={["8214d6473acefe9e:33"]="逃脱的冷却时间缩短一半。"}}
D.SpellTexts[162119]={Description={["6dd98864c1cad9b7:28"]=S[9106]}}
D.SpellTexts[162124]={Description={["91031295d63f34e0:99"]="螺旋打桩会周期性对你的存在作出反应。它们会潜伏更久并阻碍你的移动。"}}
D.SpellTexts[162127]={Description={["bb0bf5b2bc0f8fdf:130"]="反手一击，对施法者前方的目标造成物理伤害。食人魔尤为卑鄙，可以通过攻击其他食人魔来使其昏迷。"},Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[162135]={Description={["f0a4faa57998de20:55"]="右键点击以召唤或解散你的仿真机械霜鬃野猪。"}}
D.SpellTexts[162141]={Description={["87caca7a0e75b843:16"]="冲向一个目标。"}}
D.SpellTexts[162155]={Description={["e39d2c1d2bf6959a:60"]=S[11931]}}
D.SpellTexts[162156]={Description={["8ed2b6362633f2a7:50"]=S[11931]}}
D.SpellTexts[162162]={Description={["122b1e45bf3fc2ae:60"]="跳至高处开始施放X21-01A导弹速射。"}}
D.SpellTexts[162171]={Description={["5c92e25495d78d47:60"]="铁路主管箭火飞向附近的位置继续攻击。"}}
D.SpellTexts[162232]={Aura={["1a03c6693857a4ac:12"]="打断。"}}
D.SpellTexts[162239]={Description={["a641195aea83ffbb:92"]="施法者呼出锥形充能闪电。在锥形范围内的敌人每秒受到自然伤害。"}}
D.SpellTexts[162254]={Aura={["2076fba882828175:24"]=S[15366]}}
D.SpellTexts[162257]={Description={["938754a1981ce230:118"]="施法者向四面八方呼出充能闪电。位于闪电路径上的敌人将受到自然伤害。"}}
D.SpellTexts[162263]={Aura={["2076fba882828175:24"]=S[15366]}}
D.SpellTexts[162270]={Description={["d7dabf414867fabe:52"]=S[17562]}}
D.SpellTexts[162273]={Description={["f2617b01233640a0:23"]="终结一个濒死的敌人。"}}
D.SpellTexts[162280]={Description={["33373c334f64b946:39"]=S[16862]},Aura={["0823a9f70e156bf4:21"]=S[20520]}}
D.SpellTexts[162287]={Description={["f72cfc69285af7a6:246"]="只要泰克图斯受到活体之山效果影响，他就无法被杀死。\r\n\r\n他将周期性获得能量，损失的生命值越多，获得能量的速度越快。\r\n\r\n当泰克图斯引导地质剧变时，将消耗活体之山效果，使他更易受到伤害。"}}
D.SpellTexts[162313]={Description={["5d4ddc13b79f266e:40"]="短时间内改变饮用者的性别。"},Aura={["d40bd5a847c201cb:15"]="已变性。"}}
D.SpellTexts[162315]={Aura={["70bae8c4f7230083:84"]="由于赢得了荣誉，你得到了离开剑圣洞穴和哈瓦洛的安全路线。"}}
D.SpellTexts[162319]={Description={["ce2c6a92964e68bf:86"]=S[2855]},Aura={["a5572d2275fa519d:61"]="对附近敌人造成冰霜伤害并降低急速和移动速度。"}}
D.SpellTexts[162320]={Description={["ce2c6a92964e68bf:86"]=S[2855]}}
D.SpellTexts[162321]={Description={["06d05c0ce937393f:61"]="发出一记强大的怒吼，提高所有盟友的急速。"}}
D.SpellTexts[162332]={Description={["ecd965b7bdb05a2a:66"]=S[14355]}}
D.SpellTexts[162334]={Description={["ecd965b7bdb05a2a:66"]="朝一辆戈杜尼投石车投掷烟雾手雷为破坏作标记。"}}
D.SpellTexts[162339]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[162346]={Aura={["bc2e7ae2e91059b3:32"]="晶化弹幕正跟着你！"}}
D.SpellTexts[162358]={Description={["a4a94c6a3cfa7415:61"]="在黯影丛林的伊沙尔小屋附近饮用，以窥探暗影界。"}}
D.SpellTexts[162402]={Description={["062f96579a375412:11"]="看上去闪闪发光。"},Aura={["f1f5d1946566a193:14"]="你觉得自己很漂亮。"}}
D.SpellTexts[162410]={Aura={["55dd51ab5a91af70:25"]="你觉得脚步轻盈。"}}
D.SpellTexts[162421]={Description={["55e5fd1fa6cdae0c:63"]="释放出一波灼热的熔岩，对附近敌人造成火焰伤害。"}}
D.SpellTexts[162426]={Description={["5f02c76de13e6836:58"]=S[19157]}}
D.SpellTexts[162427]={Aura={["014ec4cf139b28d4:74"]="扭曲虚空已连通了纳格兰，具体位置就在沃舒古周围的幽魂林地。"}}
D.SpellTexts[162475]={Aura={["f042c4df679c3c42:23"]="粉碎，易受伤害。"}}
D.SpellTexts[162480]={Aura={["76d64388f2e6553f:12"]=S[13476]}}
D.SpellTexts[162483]={Description={["5fa688efa4160698:77"]=S[9891]}}
D.SpellTexts[162491]={Aura={["27fc723e21dc3e0b:20"]="你被锁定了。"}}
D.SpellTexts[162497]={Description={["1347bbc83a1d43ef:69"]="贪婪的血喉冲向猎物，试图剥下目标的血肉。"},Aura={["4f98b1d8393d0727:8"]=S[19105]}}
D.SpellTexts[162501]={Description={["960efef4bcd3a3d3:161"]="施法者吸收附近的一株结果的藤蔓。藤蔓果实会使九头蛇发生反应在周围生成一片剧毒烟雾。吸入烟雾的任何敌人都会受到自然伤害。"},Aura={["a08714ed123c4b5c:46"]="吸入这些烟雾的敌人将受到自然伤害。"}}
D.SpellTexts[162508]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[162518]={Description={["62db7dcc817b9ecf:191"]="泰克图斯从地底拔出大地之柱。晃动数秒后，大地之柱会从目标位置窜出，杀死任何仍然在目标位置的玩家。\r\n\r\n当泰克图斯获得25点能量后将使用该技能。"}}
D.SpellTexts[162524]={Rank={["1044fc4216ed2ac5:5"]=S[17699]}}
D.SpellTexts[162527]={Description={["df6d81c67731ad45:79"]="开启要塞的渔夫小屋的水产品专精。"}}
D.SpellTexts[162552]={Description={["fe42563d718fb7a8:58"]="古加尔召唤黑暗笼罩城市，产生无尽的黑夜。"}}
D.SpellTexts[162563]={Aura={["ce214ca22962376b:17"]="位于暗影界。"}}
D.SpellTexts[162565]={Description={["c641f77c4c5b8673:53"]="在阿卡拉兹鸦巢的塞尔利克小屋附近饮用，以进入暗影界。"}}
D.SpellTexts[162568]={Description={["363414b29749f32b:69"]=S[5413]},Aura={["2b2c56c256ffc4e3:23"]="召唤要塞部队。"}}
D.SpellTexts[162572]={Aura={["d20344ba906cecef:23"]="被飞弹烟雾阻碍了视线。"}}
D.SpellTexts[162582]={Description={["67d2e1a7fa8cce0c:59"]="学习将兽栏升至3级所需的设计图。"}}
D.SpellTexts[162588]={Description={["9a2cd2fa3045010b:9"]=S[15703]},Aura={["9a2cd2fa3045010b:9"]=S[15703]}}
D.SpellTexts[162618]={Description={["87515ea3d464a79a:69"]="在血鬃谷从血鬃缚地者的尸体上收集一只爪子。"}}
D.SpellTexts[162638]={Aura={["3337a94c6e9bf7e3:8"]="沉默"}}
D.SpellTexts[162658]={Description={["4340bce43bda8d9b:245"]="只要活体之山碎片效果存在，泰克图斯就无法被杀死。\r\n\r\n泰克图斯会周期性获得能量，速度与生命值损失速度成正比。\r\n\r\n泰克图斯引导地质剧变时，活体之山碎片效果就会被消耗，使其更容易被击碎。"}}
D.SpellTexts[163126]={Aura={["78c1d3ea57792ead:9"]="困惑。"}}
D.SpellTexts[162674]={Description={["3ac022d557935b26:112"]="泰克图斯微粒可以被彻底杀死。但是，它们仍然会获得能量，并在达到100点能量时，施放地质剧变。"}}
