D.SpellTexts[162796]={Description={["4e6d571394597002:27"]="放置一口炼金师的大锅。"}}
D.SpellTexts[162802]={Description={["059dedfec85d4da1:33"]="这就是它被称为恶梦宝珠的原因。"},Aura={["7e7056ceae341c6f:19"]="被黑暗的幻象包围。"}}
D.SpellTexts[162887]={Description={["a669ce4203847aaf:48"]="将八张钢铁卡片收集起来以完成这副套牌。"}}
D.SpellTexts[162889]={Description={["78cc9376091c55e9:49"]="将八张月亮卡片收集起来以完成这副套牌。"}}
