D.SpellTexts[162891]={Description={["12d80dd5cd30cf50:51"]="将八张幻象卡片收集起来以完成这副套牌。"}}
D.SpellTexts[162896]={Description={["6b273162bfc814ab:49"]="绑好你的火箭背包，并点火升空。"},Aura={["899555b41b7170df:17"]="急速上升。"}}
D.SpellTexts[162898]={Aura={["e69ade40f05c6ebf:51"]="强韧的降落伞足以暂时减缓你的降落速度。"}}
D.SpellTexts[162903]={Description={["7283866bcdb286c6:64"]="九头蛇散发出的剧毒烟雾使附近的敌人受到自然伤害。"},Aura={["2076fba882828175:24"]=S[15366]}}
D.SpellTexts[162906]={Aura={["1bb5b0fed9e5ad6f:6"]="闪闪发光。"}}
D.SpellTexts[162908]={Description={["235290043fd631a3:44"]="所有九头蛇的血对敌人而言都是剧毒。"},Aura={["68c07bc5e81862c0:49"]="近战攻击有一定几率造成额外的自然伤害。"}}
D.SpellTexts[162924]={Description={["7374606cd092a59d:81"]="被附近的成鸟警告，幼鸟向前冲刺，对任何遇到的敌人造成物理伤害。"}}
D.SpellTexts[162946]={Description={["57d068510ea5e57a:74"]="生成一道龙卷风沿施法者前方一条直线前进，造成自然伤害。"}}
D.SpellTexts[162969]={Aura={["42ad57cd5148b798:7"]=S[15701]}}
D.SpellTexts[162984]={Description={["0ef4fe57e98d94e2:38"]="使野兽战斗宠物升一级。"}}
D.SpellTexts[162997]={Description={["cca13f15866eedae:35"]="你的坐骑将变成战火梦魇兽。"},Aura={["cca13f15866eedae:35"]="你的坐骑将变成战火梦魇兽。"}}
D.SpellTexts[163016]={Description={["9c2239c543470794:47"]="召唤或解散一匹可供骑乘的战火梦魇兽。"}}
D.SpellTexts[163024]={Description={["6d5a50159edc1b14:113"]="召唤或解散一匹可供骑乘的战火梦魇兽坐骑。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[163025]={Description={["8292c5b613776355:109"]="召唤或解散一头可供骑乘的狞笑掠夺者坐骑。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[163035]={Description={["8ea601b255a8cdd7:39"]="冲向敌人，造成物理伤害。"}}
D.SpellTexts[163043]={Description={["f23c4a2187f9f97e:78"]="虽然克雷拉斯是个纵火狂，但他在战斗中却能时刻保持冷静。"}}
D.SpellTexts[163044]={Description={["a55729eecaee8779:115"]="赛琳娜早已没有了学徒时期的坏脾气，现在的她，以其沉稳睿智和对魔法艺术的热忱而为人所知。"}}
D.SpellTexts[163048]={Description={["986a90b56b72f656:73"]="在周围胡乱抽打，使敌人丢弃武器并造成物理伤害。"},Aura={["d8b3187c35338301:9"]=S[19046]}}
D.SpellTexts[163051]={Aura={["bf23716d6182272c:58"]="靠近屠夫或在周围2码范围内有玩家时爆炸。"}}
D.SpellTexts[163060]={Description={["c5e31b62cbf6b565:23"]="用水扑灭火！"},Aura={["c5e31b62cbf6b565:23"]="用水扑灭火！"}}
D.SpellTexts[163065]={Aura={["a2b12a80db82212b:37"]="偶尔触发狂风打击。"}}
D.SpellTexts[163068]={Description={["b063ee7ca784fc2d:26"]=S[359]},Aura={["b063ee7ca784fc2d:26"]=S[359]}}
D.SpellTexts[163070]={Description={["b063ee7ca784fc2d:26"]=S[359]},Aura={["b063ee7ca784fc2d:26"]=S[359]}}
D.SpellTexts[163076]={Description={["6b963b4d80f3aca6:30"]="不断攻击使其获得经验。"},Aura={["6b963b4d80f3aca6:30"]="不断攻击使其获得经验。"}}
D.SpellTexts[163077]={Description={["0cfcbc5ee39c8497:64"]="向施法者面前的敌人喷吐岩石，造成自然伤害。"}}
D.SpellTexts[163083]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[163085]={Description={["868fe76eea33448d:34"]="用这些鹅卵石摧毁催眠花。"}}
D.SpellTexts[163093]={Description={["36da503a5d26b24b:56"]="将火焰的精华注入黑石氏族的武器。"}}
D.SpellTexts[163111]={Description={["5139e7faab66edc5:46"]="向敌人投掷熔岩，造成火焰伤害。"}}
D.SpellTexts[163113]={Description={["219e01688ca2d3df:91"]="这个蘑菇将会随时间流逝而凋零。随着时间的持续，蘑菇的衰退速度也会加快。"},Aura={["1ea4dc9fb7fb29b6:31"]=S[20035]}}
D.SpellTexts[163116]={Description={["c7aee70ddb77c0c8:67"]="用大地碎片和矿石轰击周围的敌人，造成自然伤害。"}}
D.SpellTexts[163124]={Description={["1ea4dc9fb7fb29b6:31"]=S[20035]},Aura={["1ea4dc9fb7fb29b6:31"]=S[20035]}}
D.SpellTexts[163138]={Description={["00bdf67b528bd32e:37"]="该单位的攻击会造成蚀脑真菌效果。"},Aura={["00bdf67b528bd32e:37"]="该单位的攻击会造成蚀脑真菌效果。"}}
D.SpellTexts[163141]={Description={["3149f42653387d07:19"]="召唤一个蚀脑真菌。"}}
D.SpellTexts[163142]={Description={["c0d6a91326b24b44:26"]="召唤一个真菌食肉者。"}}
D.SpellTexts[163147]={Aura={["c75892434d29efaa:78"]="你感觉自己更加强壮，也更加敏捷了，但孢子令你窒息，并模糊你的视线。这下糟了……"}}
D.SpellTexts[163160]={Description={["a871bdcffadeac2a:64"]="施法者原地旋转，用武器造成物理伤害。"}}
D.SpellTexts[163164]={Description={["2b10bf5325e2e5f4:85"]="将十份暗色龙鳞碎片拼凑成一份完整的暗色龙鳞。"}}
D.SpellTexts[163165]={Description={["e2c024ce5512f5bb:96"]="使用磨魂者窃取敌人的一部分灵魂。施法者将获得该敌人所属职业的一项技能。"},Aura={["6729c8af425b15d2:75"]=S[15822]}}
D.SpellTexts[163166]={Description={["c89e2dcf48fe116c:56"]="奥舍尔猛地扑向受害者，并用其锐利的爪子疯狂撕扯。"}}
