D.SpellTexts[163179]={Description={["ac4e73eb123fb7a4:73"]="将十份冰冷的龙鳞碎片拼凑成一份完整的冰冷的龙鳞。"}}
D.SpellTexts[163186]={Description={["8ab45681da11120e:73"]="将十份蛛魔几丁质碎片拼凑成一份完整的蛛魔几丁质。"}}
D.SpellTexts[163187]={Aura={["76d64388f2e6553f:12"]=S[13476]}}
