D.SpellTexts[163190]={Description={["dad817d033693533:94"]="将十份厚裂蹄牛皮碎片拼凑成一份完整的厚裂蹄牛皮。"}}
D.SpellTexts[163191]={Description={["7d2e7abd05e8432c:86"]="将十份水晶能量皮革碎片拼凑成一份完整的水晶能量皮革。"}}
