D.SpellTexts[163195]={Description={["cb4a372e4fb44773:66"]="将十份魔皮碎片拼凑成一份完整的魔皮。"}}
D.SpellTexts[163197]={Description={["6cc83e1fde7a1e32:36"]="让附近的小动物见识见识锤子的力量。"}}
D.SpellTexts[163202]={Description={["5c1d1f211f408a70:85"]="将十份虚空龙鳞碎片拼凑成一份完整的虚空龙鳞。"}}
D.SpellTexts[163203]={Description={["bfe4c34db72afe5a:71"]="将十份眼镜蛇鳞片碎片拼凑成一份完整的眼镜蛇鳞片。"}}
D.SpellTexts[163204]={Description={["63c7bf03fc05a3b6:69"]="将十份风鳞碎片拼凑成一份完整的风鳞。"}}
D.SpellTexts[163205]={Description={["e919ea5b5358cdec:72"]="将五份结缔皮碎片拼凑成一份结缔皮。"}}
D.SpellTexts[163206]={Description={["ee407e9c5f9ce917:68"]="将三份破烂的皮革拼凑成一份轻皮。"}}
D.SpellTexts[163219]={Description={["de4c7836a5d692ed:32"]="与你的小队成员交换外形。"},Aura={["96022e775511faf6:18"]="交换外形。"}}
D.SpellTexts[163233]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[163235]={Description={["b25b509d9fbe6756:25"]="波加尔正在折磨你的灵魂！"}}
D.SpellTexts[163259]={Description={["aa7fb58f503d67fa:23"]="掷向箭靶。"}}
D.SpellTexts[163287]={Description={["51c74e8727c63d6a:52"]="在阴影中穿行，攻击一名敌人数次。"}}
D.SpellTexts[163297]={Description={["3086913ce8e4167d:22"]="被奥术能量扭曲。"},Aura={["3086913ce8e4167d:22"]="被奥术能量扭曲。"}}
D.SpellTexts[163308]={Description={["78b33f6bf6e7f570:54"]="向一名敌人射出混乱能量箭，造成混乱伤害。"}}
D.SpellTexts[163313]={Description={["1b4db8cbd6df388e:80"]="从空中召唤一阵流星，每秒对附近敌人造成奥术伤害。"},Aura={["a6a220295b631d14:25"]=S[5388]}}
D.SpellTexts[163314]={Aura={["a6a220295b631d14:25"]=S[5388]}}
D.SpellTexts[163320]={Description={["ab11f32f1fe9fea6:55"]="在锥形范围内吐出冰霜，造成冰霜伤害并诱捕目标。"}}
D.SpellTexts[163321]={Description={["eed02dda7958f123:68"]="受到扭曲奥能强化，旋风斩现在会牵引附近玩家。"}}
D.SpellTexts[163322]={Description={["f9b4c776a41ca367:50"]="焚烧滑溜溜的苔藓，并提供爆裂灌注效果。"},Aura={["2e9d3d978d6de91a:24"]="焚烧滑溜溜的苔藓。"}}
D.SpellTexts[163324]={Description={["e2487eb1476b667a:13"]="你看上去很脏。"},Aura={["e2487eb1476b667a:13"]="你看上去很脏。"}}
D.SpellTexts[163329]={Aura={["9fdbe41063141823:7"]="诱捕。"}}
D.SpellTexts[163332]={Description={["6818fe2014a50ed9:55"]="吐出一道锥形的火焰，造成火焰伤害并点燃目标。"}}
D.SpellTexts[163333]={Aura={["6c48b389c1b0ac2c:7"]=S[17142]}}
D.SpellTexts[163336]={Aura={["06c1c518c24c4f75:21"]=S[20516]}}
D.SpellTexts[163337]={Description={["2627deecd12f4405:65"]="在锥形范围内吐出酸液，造成自然伤害并降低目标护甲值。"}}
D.SpellTexts[163338]={Aura={["3aa1cb10ec7044af:13"]=S[12119]}}
D.SpellTexts[163349]={Description={["5b3e6306a4c0caff:48"]="用灵魂之火点燃附近的一个仪式火堆。"}}
D.SpellTexts[163359]={Aura={["96a6ecaa8e80ed6d:26"]="正在改变当前位置……"}}
D.SpellTexts[163363]={Description={["e2c024ce5512f5bb:96"]=S[2390]},Aura={["b032705b8cab8c2a:77"]="窃取了你的一部分灵魂！\r\n从附近敌人身上获得一项强大的职业技能。"}}
D.SpellTexts[163364]={Description={["e2c024ce5512f5bb:96"]=S[2390]},Aura={["6729c8af425b15d2:75"]=S[15822]}}
D.SpellTexts[163373]={Description={["80e8b21fe701ee5c:44"]=S[7582]}}
D.SpellTexts[163374]={Aura={["5adc37d9aa4e2d72:47"]=S[12943]}}
D.SpellTexts[163381]={Description={["362b110836850eaf:33"]="打开痛楚堡垒的大门。"}}
D.SpellTexts[163390]={Description={["eb971982a0e23cbb:100"]="妮莎预判你的移动方向并小心地调整陷阱发射器，在你的脚下掷出8个食人魔陷阱。"},Aura={["3b9ef9b6fefaf1a1:23"]="在你附近发射陷阱。"}}
D.SpellTexts[163393]={Description={["fe7e08cf4a322856:119"]="熊形态和猎豹形态下的移动速度提高至史诗级坐骑速度。\r\n\r\n不会与其他永久性加速效果叠加。"},Aura={["0ff8892a857d4c7b:70"]="在纳格兰时，巨熊形态和猎豹形态下的移动速度相当于史诗级坐骑的速度。"}}
D.SpellTexts[163404]={Description={["993c9d04addd94db:61"]="喷出冰晶在目标位置生成冰霜之地。"}}
D.SpellTexts[163408]={Description={["256ae73942dfb468:36"]="降低热血咆哮的加成效果。"}}
D.SpellTexts[163418]={Description={["0a3114afd4c95220:21"]=S[5075]},Aura={["582b3498fb8eb143:12"]="变形。"}}
D.SpellTexts[163441]={Description={["75236b3d08b5a10a:53"]="向当前目标射出一道棱柱光束。"},Aura={["741c3dc3a2008288:14"]="标记目标。"}}
D.SpellTexts[163447]={Aura={["b2b7593372231a46:32"]="爆裂之矛即将向你袭来！"}}
D.SpellTexts[163451]={Description={["4fc5c1cdd8f6f46e:36"]="正在地下潜行！谁知道他会从哪儿冒出来？"}}
D.SpellTexts[163454]={Aura={["a7a537b11e433176:25"]="定身！\r\n平静！\r\n沉默！"}}
D.SpellTexts[163455]={Description={["ed3338d11f86d912:54"]="向目标位置投掷不稳定的矿石，如果没有被接住则会被摧毁。"}}
D.SpellTexts[163472]={Description={["c4648f96ea5a028d:189"]="元首马尔高克利用符文石的能量来控制所有接触过溢流能量的玩家心智。该效果会使玩家免疫所有魔法伤害，并在玩家生命值降到20%以下时被移除。"},Aura={["dbad07456b30fb30:65"]="免疫所有魔法伤害。\r\n\r\n该效果在玩家生命值降到20%以下时被移除。"}}
