D.SpellTexts[163516]={Description={["362b110836850eaf:33"]="打开痛楚堡垒的大门。"}}
D.SpellTexts[163517]={Description={["05082545bbeaad82:97"]="被统御之力控制的玩家会损失5%的护盾并给予克拉戈5%的护盾。"}}
D.SpellTexts[163518]={Aura={["59953428663324d1:60"]="充满强大奥术能量的护盾保护凯尔娜拉免受所有伤害。"}}
D.SpellTexts[163522]={Description={["f94a3a2f33c1fbbe:50"]="制造令人作呕的臭气弹，没人能忍受那股恶臭。"},Aura={["cb9e6910f6b159f3:19"]="气味令人作呕！"}}
D.SpellTexts[163532]={Description={["1f86ff42ae7350a5:76"]="熔渣池只要继续存在于该区域，就会持续加热山脉之心。"}}
D.SpellTexts[163539]={Aura={["67029e94fb06e985:19"]=S[20527]}}
D.SpellTexts[163550]={Aura={["67029e94fb06e985:19"]=S[20527]}}
D.SpellTexts[163568]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
