D.SpellTexts[164924]={Description={["c250fa58fd2e49db:152"]="施法者周期性在附近生成渗穴，将附近的玩家拉向中心。被拉到中心的玩家将受到大量物理伤害。"},Aura={["87c1a31151b25308:24"]="在附近生成渗穴。"}}
