D.SpellTexts[164929]={Description={["55b9e86cabf252d1:230"]="施法者向附近敌人喷吐数个土锥。每个土锥会对冲击点造成物理伤害，并形成一道扩散的震荡波，对所有没有及时起跳的玩家造成伤害。\r\n每个土锥会额外弹跳两次，并造成余震。"},Aura={["3e3a226e456b016d:22"]=S[9731]}}
D.SpellTexts[164934]={Description={["314eea834f7448ae:163"]="施法者向附近敌人喷吐数个土锥。每个土锥会分裂成数个更小的土锥向外扩散，并对沿途触碰到的所有玩家造成物理伤害。"},Aura={["3e3a226e456b016d:22"]=S[9731]}}
