D.SpellTexts[164944]={Description={["cfca3c391246f2bc:245"]="施法者喷射出不稳定的土球，土球会向空中射出带电沙尘并在空中分裂。随后生成的带电云层会在目标区域落下闪电箭，对范围内的所有玩家造成自然伤害。\r\n土球会额外弹跳2次，每次都会生成一场风暴。"}}
