D.SpellTexts[165102]={Description={["1e33895f6aa8f498:247"]="古加尔将一名随机玩家吞噬到黑暗之中，吸收其受到的所有治疗量并储存为熵能。\r\n\r\n当无尽黑暗被移除后，熵能将被释放。该效果会为所有玩家施加吸收效果，数值相当于吸收的治疗总量，由所有玩家均摊。"},Aura={["a46347ab3be028cc:45"]="吸收所有受到的治疗量，将其储存为熵能。"}}
