D.SpellTexts[166212]={Description={["54e95b281eaade3b:56"]="移除幻影，对10码内的敌人造成伤害并使其昏迷。"}}
D.SpellTexts[166222]={Description={["5f0dd17e52439b9d:172"]="这支火焰喷射器会随着使用时间产生热量。使用后，火热喷射器需要5秒时间才会开始冷却。随后冷却过程会越来越慢。"}}
D.SpellTexts[166225]={Description={["3861dd3aefa562d1:81"]=S[13282]}}
D.SpellTexts[166302]={Aura={["2052fd2f7e3b6974:113"]="这位布林顿正在进行某些重要的事情时被招来了……看起来有点不高兴。你最好找个机会跟他聊聊。"}}
