D.SpellTexts[166335]={Aura={["cac7208cbb1a0c63:54"]="被攻击时对敌人造成连锁自然伤害。\r\n吸收伤害。"}}
D.SpellTexts[166340]={Description={["1a30d3bf7ac8eda4:104"]="在地上形成一个电能池，对池内的敌人周期性造成自然伤害。"},Aura={["cc59311d3db4d454:21"]=S[20626]}}
