D.SpellTexts[166462]={Description={["9bcfa569dbd3aee0:170"]="怨毒之种效果结束时会使受到影响的玩家喷出恶魔能量，任意接触到怨毒绽放的玩家都会感染上怨毒之种。"}}
D.SpellTexts[166464]={Description={["ae4925505408061b:58"]="施法者向目标射出火球，造成火焰伤害。"}}
D.SpellTexts[166465]={Description={["bd565a76f331fc11:60"]="施法者朝目标射出寒冰箭，造成冰霜伤害。"}}
D.SpellTexts[166466]={Description={["570f502cd1614b3f:69"]="施法者用奥术能量冲击目标，造成奥术伤害。"}}
D.SpellTexts[166471]={Description={["c794aeac020cd15b:43"]="让卡鲁回到鸦语者营地。"}}
D.SpellTexts[166474]={Description={["51f131c85e1bef4f:78"]="宿主大脑里的孢子现在长出了蛹壳，保护其不被干扰。"},Aura={["2bdec10e82c21051:25"]="免疫打断效果。"}}
D.SpellTexts[166475]={Description={["7d5385bd560d35fe:57"]="孢子掌握了拥有火焰魔法潜力的大脑区域。"}}
D.SpellTexts[166476]={Description={["48f2835371d1845c:58"]="孢子掌握了拥有冰霜魔法潜力的大脑区域。"}}
D.SpellTexts[166477]={Description={["fad96181981fc28e:59"]="孢子掌握了拥有奥术魔法潜力的大脑区域。"}}
D.SpellTexts[166489]={Description={["4c78554e80b6ce87:211"]="施法者射出火焰，快速引爆附近所有火焰花种子。当火焰花爆炸时，将生成一股快速扩张的火环对没能跳开的所有敌人造成火焰伤害。"}}
D.SpellTexts[166492]={Aura={["a162ee2f57622d38:20"]=S[15364]}}
D.SpellTexts[166495]={Description={["aea2f4aca602a367:46"]="周期性地使附近所有守卫因恐惧而逃跑。"},Aura={["70a0394296a9e2bd:14"]=S[6323]}}
D.SpellTexts[166496]={Description={["924b73d359960c4e:43"]="周期性地使附近守卫因恐惧而逃跑。"},Aura={["89dbcb1357382b6a:45"]="周期性地使附近守卫因恐惧而逃跑。"}}
