D.SpellTexts[166617]={Description={["b0429b4181092d84:53"]="向目标射出稳定的奥术箭弹幕。"},Aura={["b0429b4181092d84:53"]="向目标射出稳定的奥术箭弹幕。"}}
D.SpellTexts[166626]={Description={["71e75f83a5677d0e:73"]="这个生物并不是最优秀的战斗单位，可能会在长时间战斗后死亡。"}}
D.SpellTexts[166629]={Description={["645c050df71280a8:30"]=S[9300]}}
