D.SpellTexts[166636]={Description={["384a042c63fc8d4f:63"]="向目标和附近敌人吐出冰冷的胆汁，造成冰霜伤害。"}}
D.SpellTexts[166637]={Description={["fc54c892c8bbe8e5:71"]="扫击一名敌人的双腿，造成物理伤害并打断施法。"}}
D.SpellTexts[166650]={Description={["7fb5beb5e34ba076:31"]="以恶魔法术保护施法者。"},Aura={["4ee7b4103d18458f:35"]="暂时受到恶魔法术的保护。"}}
D.SpellTexts[166658]={Description={["daf24153306837c8:47"]=S[9714]}}
D.SpellTexts[166661]={Description={["88aade3f0ad1c41c:23"]="烧灼阿尼玛的伤口。"}}
D.SpellTexts[166676]={Aura={["67029e94fb06e985:19"]=S[20527]}}
D.SpellTexts[166684]={Description={["03f8f54681b9f8d7:109"]="虽然会在齿间留下半嚼的蟑螂腿，但是嘎嘣脆鸡肉味，连走路都觉得轻盈了。"},Aura={["b2a003ddc9716ea2:19"]="你的移动速度加快了。"}}
D.SpellTexts[166687]={Description={["8f8f39c7b50bbd2a:115"]="这块野猪排里面基本还是生的，但外面已经如炭一般焦黑。虽然让你感到恶心，但比之前更强壮了。"}}
D.SpellTexts[166695]={Description={["d3dfdce2e585edd7:60"]=S[9339]}}
D.SpellTexts[166714]={Description={["35b755a840df3e1f:55"]=S[17444]}}
D.SpellTexts[166717]={Description={["30211bf44785e097:16"]="解救这只蟾蜍！"}}
D.SpellTexts[166719]={Description={["9b31b7b5d22da3d8:170"]="种子已经在目标的大脑中发芽。长成后控制受害者的行为，经常使受害者做出被控制前力不能及的事情。"},Aura={["adb9f79cf6a8cca7:57"]="受到精神控制。\r\n施法者在施放简单法术时可以移动。"}}
D.SpellTexts[166726]={Description={["e29221ed85327ffe:88"]="在受害者头上降下冻雨，对范围内的敌人每秒造成一次冰霜伤害。"},Aura={["5485cc077b6a12b2:23"]="每秒造成冰霜伤害。"}}
D.SpellTexts[166750]={Description={["92531d9a48f70fc3:28"]="将任意增能转换为护盾。"}}
D.SpellTexts[166751]={Description={["c93fd4d3fbd85576:112"]="施法者向四面八方射出奥术飞弹。被击中的玩家将受到奥术伤害。"}}
D.SpellTexts[166772]={Description={["d344041c51bd6fdd:49"]=S[5855]}}
D.SpellTexts[166774]={Description={["15b497173f6f529a:74"]="撕扯泰罗克附近20码范围内的敌人，对其造成伤害并使其在3秒内流血。"},Aura={["8725a32dadf6ad66:9"]="流血。"}}
