D.SpellTexts[168629]={Description={["791bbe1508943d14:48"]=S[9327]},Aura={["791bbe1508943d14:48"]=S[9327]}}
D.SpellTexts[168636]={Description={["77ad22497ecc3736:65"]="释放出能量爆炸，对附近的敌人造成自然伤害。"}}
D.SpellTexts[168637]={Description={["e405499f45c4b14a:36"]="使所有敌人在熔火的炽火下昏迷。"},Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[168643]={Description={["f427e8064f226b5d:20"]="招募乌娜·斯莱舍。"}}
D.SpellTexts[168653]={Description={["50d5e1f6e5654e7f:79"]="强劲爆炸冲击你的敌人，造成物理伤害并将其击退。"}}
D.SpellTexts[168657]={Aura={["a87076dc90e577e5:14"]="吹泡泡！"}}
D.SpellTexts[168661]={Description={["90e54fd35fba55de:38"]="唤醒死者为通灵师而战。"},Aura={["90e54fd35fba55de:38"]="唤醒死者为通灵师而战。"}}
D.SpellTexts[168665]={Aura={["0f81caea71fadcaf:5"]="鬼魂"}}
D.SpellTexts[168690]={Description={["f293006b20938846:37"]="骨滩蜘蛛跳向目标。"},Aura={["f293006b20938846:37"]="骨滩蜘蛛跳向目标。"}}
D.SpellTexts[168696]={Description={["715ef4681b4d06d1:74"]="对施法者前方锥形范围内的敌人造成物理伤害并将其击退。"}}
D.SpellTexts[168697]={Description={["196a0951704ff8e6:23"]=S[17908]}}
D.SpellTexts[168770]={Description={["3354ec2daecedfee:79"]="用能量冲击施法者前方的区域，对敌人造成奥术伤害。"}}
D.SpellTexts[168791]={Description={["82139ee059ff32f9:44"]="用邪能魔法重构破损的建筑。"}}
D.SpellTexts[168795]={Description={["f33a937fb65d0f9c:70"]="令闪现术的冷却时间缩短一半。只能在阿什兰使用。"},Aura={["283dbaabac7df6b2:29"]="闪现术的冷却时间缩短一半。"}}
D.SpellTexts[168796]={Aura={["01ea864d9d5dc9b4:41"]="可以在阿什兰使用飞行形态。"}}
D.SpellTexts[168798]={Aura={["a25242fa77af09db:70"]=S[1950]}}
D.SpellTexts[168800]={Aura={["325733381ccd67c7:30"]="奴役恶魔现转变为恶魔转化。"}}
D.SpellTexts[168802]={Aura={["8ef8bdde3cb3e90b:68"]="当你施放审判圣契的那一刻，你就注定要将敌人绳之以法。"}}
D.SpellTexts[168803]={Aura={["af018a7ffbd018dc:50"]="可以使用升腾，牧师暂时获得飞行能力。"}}
D.SpellTexts[168804]={Description={["a354530c55542793:27"]=S[9521]}}
D.SpellTexts[168815]={Description={["196a0951704ff8e6:23"]=S[17908]}}
D.SpellTexts[168816]={Description={["481e5439da6003bc:68"]=S[7795]},Aura={["481e5439da6003bc:68"]=S[7795]}}
D.SpellTexts[168819]={Description={["777b6e9c28d66e25:82"]=S[11900]}}
D.SpellTexts[168832]={Description={["83e496e70bd6e5d6:47"]="痛饮一杯。\r\n\r\n只能在海军上将泰勒的要塞内使用。"}}
D.SpellTexts[168835]={Description={["1be76f80f93c6699:111"]="生成8个。裁缝技能越高，收获越多。\r\n\r\n还可能生成巫术之水和/或巫术之气。\r\n\r\n每天重置冷却时间。"}}
D.SpellTexts[168857]={Aura={["b6b12b993a5d75e0:83"]="当你与至少一位小队成员完成一个随机英雄难度地下城时，将获得额外金币奖励。"}}
D.SpellTexts[168864]={Description={["b1c9a9845a86ab31:77"]="重新选择德拉诺裁缝护甲的次要属性，物品等级要求在640或以上。"}}
D.SpellTexts[168868]={Aura={["19cb1343c9eaddc2:58"]="在影月谷吸引暗影鲟鱼上钩。"}}
D.SpellTexts[168877]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[168892]={Aura={["1f7eaba268fdba67:27"]="被困在剧毒蛛网内！"}}
D.SpellTexts[168899]={Aura={["46dba72dd7377c10:86"]="当你与至少一位小队成员完成一个随机团队副本时，将获得额外金币奖励。"}}
D.SpellTexts[168900]={Description={["21aa35e9dba9e8cc:32"]=S[9905]}}
D.SpellTexts[168905]={Description={["22cf26850ba7764c:164"]="寄生在施法者专精于火焰法术的大脑中的孢子被释放了！这些孢子会结合在一起生成上一位宿主的镜像，并继续使用所吸收的法术能量。"}}
D.SpellTexts[168906]={Description={["3b51214d1cf4b44a:165"]="寄生在施法者专精于冰霜法术的大脑中的孢子被释放了！这些孢子会结合在一起生成上一位宿主的镜像，并继续使用所吸收的法术能量。"}}
D.SpellTexts[168929]={Aura={["ee19bead4631fce6:32"]="用大量炮弹轰击敌人。"}}
D.SpellTexts[168931]={Description={["f7c175c9855eaec2:92"]=S[5873]}}
D.SpellTexts[168932]={Description={["f7c175c9855eaec2:92"]=S[5873]}}
D.SpellTexts[168944]={Description={["20c589a61b07c589:101"]="凶猛踩踏地面，造成地面震荡。这些震荡会对受影响的敌人造成物理伤害。"}}
D.SpellTexts[168948]={Description={["277894cbb008a36e:18"]="欺骗目标。"},Aura={["277894cbb008a36e:18"]="欺骗目标。"}}
D.SpellTexts[168962]={Description={["cdea224e35ba3579:70"]="召唤一根神圣图腾，保护附近盟友免受杜恩的地震技能伤害。"}}
D.SpellTexts[168981]={Description={["404c5b55339e7c84:137"]="快速旋转，周期性对附近敌人造成伤害。该技能的伤害随着时间持续增加，但同时破坏魔的移动速度也会降低。"},Aura={["b4555f8bd6357204:23"]=S[20533]}}
D.SpellTexts[168985]={Description={["3d5b7ef4204249ed:89"]=S[3691]},Aura={["b0eb81145a20215b:26"]="造成法术暗影伤害。"}}
D.SpellTexts[168986]={Description={["95f6013c8fb93f81:75"]="形成一枚暗影能量球向敌人飞去，轰击敌人造成暗影伤害。"},Aura={["c4727c1431f5873b:21"]=S[20521]}}
D.SpellTexts[168995]={Description={["9986a6d070a42d93:84"]="在目标位置形成一个充满恶魔能量的力场，每秒对目标造成暗影伤害。"},Aura={["c4727c1431f5873b:21"]=S[20521]}}
D.SpellTexts[168997]={Description={["ebcac7147121f0ad:49"]="迅猛旋转，打击路径上的所有敌人。"},Aura={["7f815e1d780fdac8:19"]="急速旋转。"}}
D.SpellTexts[169000]={Description={["13c15e59884dca36:97"]="快速旋转，造成伤害的同时牵引附近敌人。该技能的伤害随着时间持续增加。"},Aura={["b4555f8bd6357204:23"]=S[20533]}}
D.SpellTexts[169009]={Description={["b0ab1f3f986b98d4:71"]="小鬼的实体形态脱离这个世界，从而不会受到攻击，除非小鬼自己发动攻击。"},Aura={["2bac73a2a18910f3:13"]="无法被攻击。"}}
