D.SpellTexts[169034]={Aura={["01842bfed2c81307:14"]="下落速度放慢。"}}
D.SpellTexts[169037]={Description={["946ecc3122a01ef4:79"]="驾驶一台拥有爆炸弹射椅的机械路霸样机。这是一种风驰电掣般的载具。"}}
