D.SpellTexts[169088]={Description={["1e811c052110513c:29"]="召唤一个黑铁恐法师。"}}
D.SpellTexts[169092]={Description={["114642c19ac38a2c:104"]="较低的附魔技能在制造时可能会使水晶破裂。\r\n\r\n还可能生成巫术之气或和巫术之火。\r\n\r\n每天重置冷却时间。"}}
