D.SpellTexts[169117]={Aura={["5f4538fb467d4bbe:35"]="被迫与塞拉希尔之斧并肩战斗！"}}
D.SpellTexts[169120]={Description={["a945b4898cba55da:99"]="雅努向周围散发出生命活力，周期性在附近生成迅捷幼苗、恶毒妖花和多瘤古树。"}}
D.SpellTexts[169134]={Description={["1f19632b1bc8a7ee:36"]="跳跃有一定几率触发飞跳腿。"},Aura={["1f19632b1bc8a7ee:36"]="跳跃有一定几率触发飞跳腿。"}}
D.SpellTexts[169135]={Description={["634b30d84ecfa811:41"]="跳跃吞噬者残肢使你获得了飞跳腿！"},Aura={["634b30d84ecfa811:41"]="跳跃吞噬者残肢使你获得了飞跳腿！"}}
