D.SpellTexts[169138]={Description={["2f422ecbb5509006:11"]="到处跳！"},Aura={["2f422ecbb5509006:11"]="到处跳！"}}
D.SpellTexts[169140]={Description={["8ac33861fb415ae6:139"]="一旦你拥有了终极版侏儒军刀，你就可以将没有起搏器的军刀卖给那些不是工程师的蠢货了。"}}
D.SpellTexts[169148]={Description={["46ca62650dc32982:94"]=S[13348]}}
D.SpellTexts[169150]={Description={["ed4dd4d4d66a47db:100"]="施法者快速飞跃当前目标并对仍然留在飞行路线上的所有目标造成自然伤害。"}}
D.SpellTexts[169153]={Description={["eaf38640d0081a79:24"]=S[5251]}}
D.SpellTexts[169154]={Description={["eaf38640d0081a79:24"]=S[5251]}}
