D.SpellTexts[169157]={Description={["98a0ac9f947b4558:83"]="跃向目标附近的某个位置并向前方锥形范围吐出邪火，造成一次火焰伤害。"},Aura={["67029e94fb06e985:19"]=S[20527]}}
D.SpellTexts[169170]={Aura={["bb1fe4da49b0942b:22"]="每3秒受到一次自然伤害。"}}
D.SpellTexts[169172]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[169174]={Description={["115eaf6e2d3ea0a7:160"]="施法者向附近敌人投掷数个毒液瓶。击中敌人后，每个毒液瓶会生成一团致命毒气，对范围内的玩家造成自然伤害。"}}
D.SpellTexts[169179]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[169183]={Aura={["67029e94fb06e985:19"]=S[20527]}}
D.SpellTexts[169195]={Description={["7c7303f53a2ca20c:32"]="从死去的鬣蜥人身上移除水晶。"}}
D.SpellTexts[169214]={Description={["50be3c021ee224ed:127"]="受到伤害有一定几率向一名敌人喷出血液，使得法术或技能击中敌人后恢复最大生命值的5%。"},Aura={["8ea7c322579e3c11:87"]="攻击者有几率获得活力之血效果，攻击命中后可以恢复生命值。"}}
D.SpellTexts[169216]={Description={["61906d396aafdf3e:58"]="焚烧古树残骸，阻止种子的生成。"}}
D.SpellTexts[169223]={Description={["f3725fc8047bbac1:158"]=S[15344]},Aura={["2076fba882828175:24"]=S[15366]}}
D.SpellTexts[169224]={Description={["f3725fc8047bbac1:158"]=S[15344]}}
D.SpellTexts[169233]={Description={["10a0334119f302f2:91"]="兽人会吸入小蜘蛛死后留下的毒气。如果成功，兽人就会获得剧毒之血效果。"}}
D.SpellTexts[169235]={Aura={["c1b02789d425c01a:14"]="被困在时光内。"}}
D.SpellTexts[169240]={Aura={["73d0210945d1dd3c:41"]="昏迷。\r\n每秒造成一次自然伤害。"}}
D.SpellTexts[169249]={Aura={["b2576b76b731cf07:14"]="快被吃掉了。"}}
D.SpellTexts[169251]={Description={["f82d01654fbe1168:183"]="雅努向一名随机肯瑞托战斗法师投掷木刃，生成植物并困住他们。该效果会使肯瑞托战斗法师昏迷并每秒造成一次自然伤害，直到纠缠的植物被摧毁为止。"}}
D.SpellTexts[169265]={Description={["af20c95c2f81041f:27"]="雅努创造出了一把新的木刃。"}}
D.SpellTexts[169268]={Aura={["2c6ebae9c699488a:13"]="已过载。"}}
D.SpellTexts[169270]={Description={["26c8909afb7eaeb5:66"]="艾里塔克的剧毒会在它落地的地方留下一滩毒气。"}}
