D.SpellTexts[170740]={Description={["17f6e594d5cc1485:83"]="使你下一个法师法术变成瞬发。对变形术、传送法术和传送门法术不起作用。"},Aura={["b6e63848dfe2b951:71"]=S[1888]}}
