D.SpellTexts[171078]={Description={["d092301d270962cc:159"]="暴虐的艾罗萨恩在同时受到浸水和着火了效果影响的目标身上触发蒸汽动力反应。随后的蒸汽冲击会造成大量火焰伤害并将敌人打飞。"}}
