D.SpellTexts[171107]={Description={["0ae2d9a67bbf6be3:70"]="对附近敌人造成冰霜伤害，且如果目标受到着火了效果影响，则将火焰扑灭。"}}
D.SpellTexts[171112]={Description={["b944cde38e320a26:63"]="对附近敌人造成火焰伤害，并移除其身上的浸水效果。"}}
