D.SpellTexts[171192]={Description={["3798549ab9401c8b:117"]="缚魂者图拉妮很小的时候就失去了家人。大主教玛拉达尔收养了这名聪明活泼的小德莱尼并当做自己的孩子将她抚养长大。"}}
