D.SpellTexts[171200]={Description={["c8467a24396b6c6f:127"]="当查尔·恐翼施放白热地狱时，献祭余烬会急剧升温。对大范围内的敌人造成火焰伤害。"}}
D.SpellTexts[171202]={Description={["2dc0994f73cdb2d0:146"]="艾达·晨光坚持并不是所有术士都是“邪恶“的。当然，他们会召唤恶魔并且使用暗影魔法，但为什么这样的力量就不能用在正道上呢……是吧？"}}
D.SpellTexts[171204]={Description={["039bb0dea024f4ff:42"]="小心地将毛皮从长毛裂蹄牛身上剥下。"},Aura={["1228721f9c640670:12"]="已被剥皮。"}}
D.SpellTexts[171221]={Description={["d5816bf647ecee6d:176"]="艾萝娜一直梦想着有朝一日能够加入古老的奥金尼骑士团。当大主教玛拉达尔向所有德莱尼志愿者发出征召时，艾萝娜毫不犹豫地执起祖父的甲胄，义无反顾地奔赴她的使命。"}}
D.SpellTexts[171222]={Description={["3383af8e6576dcb9:42"]="召唤或解散神秘的春日花束。"}}
D.SpellTexts[171234]={Description={["bff819c516cd9988:41"]="神奇地将你对世界的感知进行了过滤。"},Aura={["7175b6db619983b2:19"]="已过滤感知。"}}
D.SpellTexts[171239]={Description={["1b4f005b556882ce:89"]="击碎大地爆发出邪能能量，对任何被击中的敌人造成火焰伤害。"},Aura={["67029e94fb06e985:19"]=S[20527]}}
D.SpellTexts[171244]={Description={["5611671d716b50e6:201"]="当残酷的兽人袭击他的家园时，阿姆被剑圣巴罗克俘虏了。兽人不断折磨阿姆，但他拒绝屈服。死后，阿姆继续徘徊在这个世界，渴望向钢铁部落和它的同党复仇。"}}
D.SpellTexts[171245]={Aura={["785be2184a7b4481:10"]=S[21316]}}
