D.SpellTexts[173193]={Description={["ed424d79e360b14c:237"]="本杰明·吉布曾是洛丹伦的一名普通农夫，之后被亡灵瘟疫夺走了性命。巫妖王看到了他作为一名恐怖战士的潜力，并将其复活成强大的死亡骑士。自从巫妖王陨落后，本杰明加入了部落的先锋军，希望能为这副饱受诅咒的躯体找到存在的意义。"}}
D.SpellTexts[173205]={Description={["2393eb15cd22ff34:127"]="暗影牢笼将伤害辐射给每个目标，使其落马，被诱捕，并对路径上的敌人每秒造成一次暗影伤害。"}}
