D.SpellTexts[173956]={Description={["a6320466163d8945:45"]=S[9816]}}
D.SpellTexts[173957]={Aura={["40adfb9ed430e67f:198"]="攻击有几率用奥术能量冲击目标，吸收治疗量并造成奥术伤害。\r\n\r\n效果消失后，吸收的治疗量会爆炸，对附近的敌人造成奥术伤害。\r\n\r\n该效果同一时间只能影响一个目标。"}}
D.SpellTexts[173958]={Description={["a6320466163d8945:45"]=S[9816]},Aura={["293af8b62827eed7:6"]="呀！"}}
D.SpellTexts[173962]={Description={["fc9e257231da1d4b:48"]="将一个目标传送到施法者前方的一个位置。"}}
D.SpellTexts[173964]={Description={["2aa6c43b97db6ef0:38"]="向目标位置投掷剧毒。"},Aura={["2aa6c43b97db6ef0:38"]="向目标位置投掷剧毒。"}}
