D.SpellTexts[174004]={Description={["07375758e8fa1e6d:65"]="在德拉诺召唤一头可供骑乘的幽灵塔布羊。这是一种非常、非常快的坐骑。"},Aura={["4fd7cafff1d3661a:9"]=S[6151]}}
D.SpellTexts[174005]={Aura={["b21d3366ae97cbab:148"]="攻击有几率用周期性暗影伤害冲击目标，附近目标数量越多，造成的伤害越大。\r\n\r\n该效果同一时间只能影响一个目标。"}}
D.SpellTexts[174011]={Description={["4f281ba31b39077a:124"]="造成暗影伤害并生成一片中立区域。该效果阻止一切攻击和施法行为但可以使你免疫所有伤害。"}}
