D.SpellTexts[174513]={Description={["1d3637b45dbd7315:95"]="将一个拍卖行储存卡插槽、连接端口和A.D.D.O.N.S.安装程序组合为一个拍卖行控制模块。"}}
D.SpellTexts[174515]={Description={["58c5899c1dc33093:85"]="将一个通用语言补偿器、过滤器和资料库组合为一个通用语言模块。"}}
D.SpellTexts[174521]={Description={["07b00ec1ce8d5984:75"]="将一个超冷却调节器、导管、制冷剂和泵机组合为一个超冷却模块。"}}
D.SpellTexts[174522]={Description={["d0dd33311fc911ea:82"]="将一个循环能源转换器、外壳、内框和定序器组合为一个循环能源模块。"}}
D.SpellTexts[174524]={Description={["12270ed3f86da86c:24"]="觉得谁棒就扔给谁！"},Aura={["64bd6ed3962909a6:27"]="有人觉得你酷炫到不行！"}}
D.SpellTexts[174528]={Description={["a7b1a75011364f5b:21"]="把这东西扔给一个讨厌鬼。"},Aura={["b3f9cc5647bbfd5b:24"]="有人看你不爽。"}}
