D.SpellTexts[174534]={Description={["4f2dcec58f6026ea:114"]=S[13294]}}
D.SpellTexts[174564]={Description={["8b9daa999b7df39e:98"]="用真菌覆盖住附近的敌人，对其造成伤害并降低其受到的治疗效果。该效果随着时间递减。"}}
D.SpellTexts[174565]={Aura={["822e4223ddb7096e:41"]="引爆附近的蘑菇，造成自然伤害。"}}
D.SpellTexts[174569]={Description={["50b6649e68e24ccd:32"]="把咖啡泼在一个打瞌睡的商人身上。"}}
D.SpellTexts[174571]={Description={["f960c645abeb72a6:28"]="想逃可没那么容易。"}}
