D.SpellTexts[174579]={Description={["6fd0970b80697944:63"]="点燃鬼火，用幽魂火焰强化施法者的武器。"},Aura={["2c7e128f02492042:36"]="近战攻击会触发一次猛烈爆炸。"}}
D.SpellTexts[174590]={Aura={["a162ee2f57622d38:20"]=S[15364]}}
D.SpellTexts[174593]={Description={["962ca2fe52327daf:83"]="释放出真菌波冲击波，对附近敌人造成自然伤害并使其攻击速度降低。"}}
D.SpellTexts[174601]={Aura={["3e7755e839d9aea7:9"]="正在钻孔。"}}
D.SpellTexts[174608]={Description={["d7b3b44cc9916119:40"]="召唤幻影武器攻击敌人。"}}
D.SpellTexts[174613]={Aura={["36046f2886e576a1:12"]="看上去很苍白。"}}
D.SpellTexts[174615]={Aura={["0c77048c69961c05:22"]="将敌人变成石头。"}}
D.SpellTexts[174618]={Description={["2117aa465ca6ee29:50"]=S[10327]},Aura={["2117aa465ca6ee29:50"]=S[10327]}}
D.SpellTexts[174619]={Description={["375a7ee3a58d5472:69"]=S[14903]},Aura={["375a7ee3a58d5472:69"]=S[14903]}}
D.SpellTexts[174620]={Description={["5d5ecd78d6e994bb:29"]=S[5335]}}
D.SpellTexts[174628]={Description={["ef59d3c2afc59857:86"]="对一名敌人造成轻微自然伤害。如果目标被石化，则伤害将大幅提高。"}}
D.SpellTexts[174634]={Description={["9184a6c99bdf935a:72"]="岩怒背上的共鸣水晶大幅加快了岩石气息的施法速度。"},Aura={["2d2382e76becc09c:42"]="岩石吐息的施法速度大幅加快。"}}
D.SpellTexts[174650]={Description={["bf50f03143384a52:146"]="召唤一群奔踏的野兽穿越荣耀之路，将敌人击飞，并造成物理伤害。\r\n\r\n只能在阿什兰的荣耀之路使用。"}}
D.SpellTexts[174662]={Description={["f7ccbf6ad752bee5:173"]="在荣耀之路祈求青龙天神的帮助，为所有友方目标恢复满生命值，并移除所有的魔法、中毒和疾病效果。\r\n\r\n只能在阿什兰的荣耀之路使用。"}}
