D.SpellTexts[174887]={Description={["480304e3c3e9e07e:89"]="艾萝娜将获得指引之光技能，允许她在野外将一名小队或团队成员召唤到你的位置。"}}
D.SpellTexts[174889]={Description={["25e09a73973f76d0:92"]="愛伊達將會獲得召喚儀式，可在野外為你召來一名隊伍或團隊成員。"}}
D.SpellTexts[174891]={Aura={["b1436e5c52b9b38f:100"]="诺赞德和他的小伙伴威布森打了你一下……虽然不怎么疼，但让你吓了一跳。"}}
