D.SpellTexts[176028]={Description={["9c593d23fe0ab880:75"]="对一名敌人造成冰霜伤害。水流喷射的力量会将目标击退。"}}
D.SpellTexts[176034]={Description={["976a532488a03ff5:183"]="向目标位置扔出一滩熔火，对火焰内的敌人造成火焰伤害。这滩熔火还会强化盟友的武器，使其近战攻击可以对目标造成额外的火焰伤害。"}}
D.SpellTexts[176038]={Aura={["34ba212d47e1cbc4:50"]="近战攻击命中后可造成额外的火焰伤害。"}}
D.SpellTexts[176043]={Description={["f1d3d917622f223a:57"]="鞭笞一名敌人，打击三次，造成物理伤害。"}}
D.SpellTexts[176047]={Aura={["3eb61b09b0f8ae7e:20"]="出土的圣物。"}}
D.SpellTexts[176049]={Description={["8d3faeff20afdf4c:60"]="奔跑速度提高数分钟。只在你的要塞矿井有效。"}}
D.SpellTexts[176057]={Description={["5df655baacbd6f29:40"]="喝一口，伪装成一个悬槌食人魔。"},Aura={["edf202f6ec05c469:32"]="只不过是个准备派对的悬槌食人魔！"}}
D.SpellTexts[176058]={Description={["6ffa5c41fd6a5ca4:20"]=S[15343]}}
D.SpellTexts[176059]={Description={["f2188fad15efbd64:149"]="使你造成的伤害提高75%，最大生命值提高75%，受到的治疗效果降低100%，并增大体型，持续45秒。\r\n只在德拉诺的户外有效。"},Aura={["e82f7aa3c55e154a:97"]="造成的伤害提高75%。最大生命值提高75%。受到的治疗效果降低100%。\r\n体型增大。"}}
D.SpellTexts[176061]={Description={["a0dee002e015baf1:59"]="暂时提高采矿速度。只在你的要塞矿井有效。"},Aura={["3388c6c07b97c07d:37"]="使你在要塞矿井内的采矿速度更快。"}}
D.SpellTexts[176065]={Description={["139058595a4c2ff0:61"]="用头撞击一个敌人，造成物理伤害并将其击退。"}}
D.SpellTexts[176068]={Description={["0d563aeb980dc590:58"]=S[2587]},Aura={["0d563aeb980dc590:58"]=S[2587]}}
D.SpellTexts[176075]={Description={["d3d5de97436696a2:267"]="维罗娜拉曾是希尔瓦娜斯手下的一名低阶游侠，但在大地的裂变时期，她在血色修道院的骄人战绩使得她平步青云。当黑暗女王征召志愿者远征德拉诺时，维罗娜拉毫不犹豫地站了出来。只要能取悦黑暗女王，冒任何险都是值得的。"}}
D.SpellTexts[176076]={Description={["8979248a547aaf9d:23"]="被高塔法师锁定。"},Aura={["8979248a547aaf9d:23"]="被高塔法师锁定。"}}
