D.SpellTexts[176090]={Description={["6ffa5c41fd6a5ca4:20"]=S[15343]}}
D.SpellTexts[176101]={Description={["457da3140cdfa243:274"]="赫尔达·影刃十分厌弃她早年作为黑铁矮人的生活，怯懦躲在黑石山的深处。当茉艾拉在三锤议会中占据了重要一席后，赫尔达就把铁炉堡当成了自己的新家，并对着自己的影刃发誓，唯茉艾拉马首是瞻。"}}
D.SpellTexts[176105]={Description={["b44fb6f8c5c9b083:70"]="发射飞弹，攻击附近的所有非双头飞龙敌人，造成火焰伤害。"}}
D.SpellTexts[176111]={Description={["fd997b511e9e9716:18"]="穿越时光。"},Aura={["13489358907de07b:111"]="穿越时间，回到未被钢铁部落入侵前的诅咒之地。\r\n\r\n和希多尔米再次交谈可以回到现在的时间点。"}}
D.SpellTexts[176118]={Description={["28fa5b3dbf025af0:67"]="恐蹄踩踏一个敌人，造成物理伤害并使其昏迷。"},Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[176132]={Description={["7b138da99f583c4a:45"]="在目标位置召唤一座活火山。"},Aura={["7b138da99f583c4a:45"]="在目标位置召唤一座活火山。"}}
