D.SpellTexts[176140]={Description={["24f2bdf73e7042e0:52"]="右键点击以召唤或解散你的哨兵之友。"}}
D.SpellTexts[176141]={Description={["75c929ea698226ab:42"]="冷固的熔渣免疫几乎所有伤害。"}}
