D.SpellTexts[176362]={Description={["e83d7053dd9d14b4:159"]="召唤一枚时间炸弹。炸弹飞向地面并在接触后爆炸。物理碰撞后的动能将转化为势能，使炸弹每次触地后都能飞得更高。"}}
