D.SpellTexts[176395]={Aura={["b3b0825eba1802cf:99"]="近战攻击命中时会向目标射出暗影烈焰箭。\r\n每命中一次，该伤害也会相应提高。"}}
D.SpellTexts[176398]={Aura={["509a17812a7ba83e:35"]="用倒刺铁链扼住敌人的脖子。"}}
D.SpellTexts[176438]={Description={["e305a7ff4021e6ce:38"]="磨去磨损的痕迹和其他所有东西！"},Aura={["1ae4319c199cb229:41"]="只要你看不见盔甲，它就不会磨损！"}}
D.SpellTexts[176440]={Description={["994f9c9ac1f3e7ef:188"]="向目标位置射出暗影烈焰之箭，并将该区域点燃。火焰会对接触到的敌人造成暗影烈焰伤害，并周期性向附近位置射出暗影烈焰箭，造成暗影烈焰伤害。"},Aura={["85a4c039ca1958f0:26"]="造成暗影烈焰伤害。"}}
