D.SpellTexts[178360]={Description={["fa049e2105f64e60:164"]="一位久经沙场的联盟英雄响应召唤，加入了荣耀之路的战场。\r\n\r\n当荣耀之路内被击杀的部落玩家达到足够数量，一位联盟队长就会被召唤入战场。"}}
