D.SpellTexts[178362]={Description={["66d58600b0b9feb3:184"]="部落在阿什兰最精锐的守卫，专职保卫战争之矛岗哨。\r\n\r\n占领落烬塔楼可以让联盟哨兵获得击杀战争之矛角斗士的技能，使部落的防御力量土崩瓦解。"}}
D.SpellTexts[178363]={Description={["2b054d7b0eefd2a2:199"]="联盟在阿什兰最精锐的守卫，专职保卫暴风之盾堡垒。\r\n\r\n占领大法师瞭望塔可以让巨魔猎头者获得击杀暴风之盾角斗士的技能，使联盟的防御力量土崩瓦解。"}}
D.SpellTexts[178373]={Aura={["096219e7b8e2e098:8"]=S[21904]}}
D.SpellTexts[178374]={Description={["d25eab9afb29c90b:28"]=S[5685]}}
