D.SpellTexts[178444]={Description={["1877cdcbc4dcd0fa:52"]="制造一件优秀、精良或史诗品质的追随者护甲强化徽记。"}}
D.SpellTexts[178445]={Description={["6600a9347f04bda5:53"]="制造一件优秀、精良或史诗品质的追随者武器强化徽记。"}}
D.SpellTexts[178461]={Description={["d37d94e4fa6309df:101"]="施法者驾驭累积的智慧力量，用灵能力量冲击敌人。受害者将遭受暗影伤害。"}}
D.SpellTexts[178473]={Description={["658581791f660dcc:65"]="用这条项链装扮一名追随者，立即将其提升为史诗品质。"}}
