D.SpellTexts[178575]={Description={["bd99ce99d37cacd8:180"]="这把钥匙可以打开那些放着积怨纳迦贡品的箱子。纳迦希望用贡品来取悦王子的父亲深须国王，让他继续支持他们的入侵行为。现在该你来享用他们的贡品了！"}}
