D.SpellTexts[179407]={Description={["91ff088c7a864607:209"]="受害者灵魂出窍，进入到暗影界。当受害者重返现世界时，会在暗影界留下一个残余能量宝珠。\r\n\r\n受害者体内的任意潜伏能量都会留在暗影界。"},Aura={["f80629178f9c74d6:23"]="你正位于暗影界。"}}
D.SpellTexts[179408]={Description={["8debd72a5da69a1d:68"]="将当前目标标记为新鲜的肉，招致附近的刃牙虎人群起而击。"}}
