D.SpellTexts[179427]={Description={["bc3730d04e3e649d:199"]="邪能领主在目标位置处制造一个邪能喷泉。如果喷泉的能量没有被及时吸收，便会转化成邪能水晶。\r\n站在邪能喷泉处10秒，会迫使受害者吸收喷泉的能量。"}}
D.SpellTexts[179428]={Description={["726c09b58ecc5bc0:56"]="站在轰鸣的裂隙上会对受害者造成火焰伤害。"}}
