D.SpellTexts[181009]={Description={["3ebc5d1840273c4b:276"]="玛克斯韦尔·泰罗索斯男爵是最早加入银色黎明的勇士之一，由于他的英勇表现，很快就得到了晋升，成为仅次于提里奥·弗丁的重要领袖。无论是在面对纳克萨玛斯的天灾军团的战斗中，还是直接与天灾领主对决之时，泰罗索斯都证明了自己是可靠的领袖，也是圣光真正的勇士。"}}
