D.SpellTexts[183170]={Description={["910ead73ed89e120:117"]="所有靠近这个瓶子的人似乎都会说不出话来，仿佛它能抽取他们的生命力一般。将它涂抹在你的武器上或许会产生更强大的效果……"},Aura={["a5098b858c1a238e:79"]="法术与攻击造成额外的暗影伤害，并为你恢复1%的最大生命值。"}}
