D.SpellTexts[184818]={Description={["89f33737539672f0:254"]="关于女伯爵莉亚德琳的性格可谓众说纷纭：狂热，骄傲，性情不定——然而这位血骑士的女领主从来不会为他人的评论所动。不管别人怎么评价，她的眼里只有一件重要的事情：完全而彻底地摧毁燃烧军团。"}}
D.SpellTexts[184819]={Description={["e2506490afb03bdd:268"]=S[1481]}}
D.SpellTexts[184825]={Description={["ead75b2f1af7b784:290"]="阿古斯之手曾经是强大的德莱尼圣骑士教团，致力于保护族人不被燃烧军团的猎杀者加害。在德拉诺遭遇了嗜血兽人的屠戮之后，骑士团的人数并没有完全恢复，但守备官波鲁斯绝不会允许他们的传统就此消亡。他全心全意地投身于恢复阿古斯之手神圣誓言的事业之中。"}}
D.SpellTexts[184832]={Description={["cb6a39ba9472d9fb:89"]="施法者将附近池子中的邪能聚集在目标身上，使其和附近玩家减速。"}}
D.SpellTexts[184852]={Description={["d93c708ca87e9d1d:108"]="受害者暴露在暗影之池能量辐射下的时间过长，以至于现在自身也会散发出暗影之池能量。"},Aura={["efa5fc30d55bc62f:26"]="辐射暗影之池能量。"}}
D.SpellTexts[184853]={Description={["9fa0fa5e66fa70c9:106"]="受害者暴露在火焰之池能量辐射下的时间过长，以至于现在自身也会散发出火焰之池能量。"},Aura={["8e70ede9db9b5ffc:25"]="辐射火焰之池能量。"}}
D.SpellTexts[184854]={Description={["58ca9bce137ffa49:102"]="受害者暴露在邪能之池能量辐射下的时间过长，以至于现在自身也会散发出邪能之池能量。"},Aura={["82ab7c41a728f4f8:23"]="辐射邪能之池能量。"}}
D.SpellTexts[184858]={Description={["6103ec868cc9665d:141"]="那些暴露在辐射之下的玩家同样会辐射出暗影之池的能量，对附近的玩家造成暗影伤害。\r\n\r\n长时间暴露在辐射之下会导致辐射疫病。"}}
D.SpellTexts[184872]={Description={["c5660821eee55612:78"]="召唤暗影之颅，造成暗影伤害并使敌人因恐惧而逃跑。"}}
D.SpellTexts[184873]={Aura={["6acaea0936cbf0fa:14"]=S[6323]}}
D.SpellTexts[184880]={Description={["241e63c727a87410:42"]="用暗影爆炸攻击附近的敌人。"}}
D.SpellTexts[184884]={Description={["292ef9a548165c50:135"]="那些暴露在辐射之下的玩家同样会辐射出火焰之池的能量，对附近的玩家造成火焰伤害。\r\n\r\n长时间暴露在辐射之下会导致辐射疫病。"}}
D.SpellTexts[184885]={Description={["d0b84ca029ae214f:138"]="那些暴露在辐射之下的玩家同样会辐射出邪能之池的能量，对附近的玩家造成自然伤害。\r\n\r\n长时间暴露在辐射之下会导致辐射疫病。"}}
D.SpellTexts[184932]={Description={["df2b5b2d66a8bc10:41"]="使用符文能量屏障保护施法者。"},Aura={["9c9b4d7eae52d7eb:7"]="免疫。"}}
