D.SpellTexts[186134]={Description={["7aac5b161cb93f13:198"]="在祖霍拉克的大厅中受到火焰伤害的玩家会在被潜伏的邪能穿过时进入邪蚀状态。\r\n\r\n如果玩家在邪蚀状态下受到暗影伤害，就会引发邪影屠戮，并结束邪蚀状态。"},Aura={["99fa5ad519abe8dc:66"]="暗影伤害会引发一次邪影屠戮。\r\n\r\n刚受到过火焰伤害。"}}
D.SpellTexts[186135]={Description={["85b3ec7ab8baef29:192"]="在祖霍拉克的大厅中受到暗影伤害的玩家会在被虚空附体时进入灵媒状态。\r\n\r\n如果玩家在灵媒状态下受到火焰伤害，就会引发邪影屠戮，并结束灵媒状态。"},Aura={["fd2291d57ef7d8c8:66"]="火焰伤害会引发一次邪影屠戮。\r\n\r\n刚受到过暗影伤害。"}}
