D.SpellTexts[186481]={Description={["cab19457b038a2a0:19"]="击晕附近的敌人。"},Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[186488]={Description={["fa5cd79f7173c10a:59"]=S[13264]}}
D.SpellTexts[186514]={Description={["913f27e27cdc43e9:42"]="将所有的8个丝纹护甲部件合成一套丝纹套装。"}}
D.SpellTexts[186519]={Description={["27033eec1334fc97:23"]="射向黑鸦堡的敌人。"}}
D.SpellTexts[186530]={Aura={["b51235fdebbc44d0:20"]=S[7760]}}
D.SpellTexts[186532]={Description={["91a505b99c44c8f8:187"]="施法者召唤一颗邪火宝珠。火焰一旦触碰到玩家，便会被其吸收，使其受到点燃的影响。\r\n\r\n如果宝珠移动很远并且没有触碰到任何玩家，便会落到地上，并生成一团混沌邪火。"}}
D.SpellTexts[186535]={Description={["fbd34a5f2ef6f8d0:41"]="施法者制造一个立方形的触发区域，5x5x5码。"}}
D.SpellTexts[186541]={Description={["16e221ecb0ba36ef:59"]="有一定几率用邪能毒害敌人，持续造成火焰伤害。"},Aura={["062957d6ad1254eb:22"]="使用邪能污秽的利刃。"}}
D.SpellTexts[186543]={Description={["9189035474456f97:61"]="召唤一道水波向前猛扑，造成冰霜伤害。"}}
D.SpellTexts[186569]={Description={["c68f86afd810b4fc:26"]="传送至另一个位置。"}}
D.SpellTexts[186574]={Description={["bdfe2b3b13e38490:53"]="恐惧猎犬随机锁定一名玩家，只对其进行攻击。"},Aura={["973cea78fb4386ab:28"]="一只恐惧猎犬锁定了你！"}}
