D.SpellTexts[186608]={Description={["82b429dc97a3a11f:41"]=S[10013]},Aura={["82b429dc97a3a11f:41"]=S[10013]}}
D.SpellTexts[186612]={Description={["6b2b92718569ac08:99"]="从地面喷出腐肉，对所有敌人造成暗影伤害，喷发造成额外的暗影伤害。"}}
D.SpellTexts[186616]={Description={["7a625a177ac54d98:39"]="石化图腾将你封到一个水晶中。"},Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[186631]={Aura={["24219cb8636792ab:36"]="能够看到游荡的恶魔影像。"}}
D.SpellTexts[186637]={Aura={["dfeaf16900ae201a:35"]="叫喊至脱力！\r\n昏迷。"}}
D.SpellTexts[186652]={Aura={["80b39822d8ea6607:58"]="剧烈爆炸。\r\n速爆火焰炸弹会更快获得能量。"}}
D.SpellTexts[186655]={Description={["f3c75a815b307518:70"]="将一座建筑或者其他什么东西点燃。对此应该有人来做点什么！"}}
D.SpellTexts[186662]={Aura={["2b092300b1ca4fcf:54"]="每施放一次阿古斯之焰，生命值就会降低25%。"}}
D.SpellTexts[186674]={Description={["1819bc4f4bedf8bc:86"]="猛烈地践踏地面，对附近的所有敌人造成火焰伤害，并将其击飞至空中。"}}
D.SpellTexts[186708]={Aura={["47078df6331f9077:68"]="你的内心感到温暖且平静……似乎找到了新的人生方向。"}}
D.SpellTexts[186733]={Description={["a49894dd6a83da9a:43"]="从你的魔蝠上跃下，扑向下方的目标。"}}
D.SpellTexts[186745]={Description={["8e494565e72f7246:43"]="投掷火把，点燃一个被遗忘者瘟疫箱子。"}}
