D.SpellTexts[186967]={Description={["1a47e03dba3aafa8:133"]=S[9702]}}
D.SpellTexts[186972]={Description={["27de628737bc7b74:127"]="瓦尔基拉总是处于艾尔的监视之中，她会打倒任何胆敢对抗他们的人。攻击有几率造成额外的神圣伤害。"},Aura={["3f3b1cad39a21858:46"]="攻击时有几率造成额外的神圣伤害。"}}
D.SpellTexts[187004]={Description={["c7cee92220aee307:86"]="将施法者传送到正前方6码的位置，路线上有阻挡物则会停止，传送可以解除施法者身上一切形式的束缚。"},Aura={["223511bd590b2328:11"]=S[21053]}}
D.SpellTexts[187017]={Aura={["9c31a7c1d64a9b6e:7"]=S[3025]}}
D.SpellTexts[187032]={Description={["76c9f98d13a5615a:105"]="召唤自然之力，使你能够跳出很长一段距离，对附近的敌人造成自然伤害，并使其昏迷。"}}
D.SpellTexts[187035]={Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[187050]={Aura={["4582de29b9eb7224:64"]="效果结束时造成暗影伤害，由附近的所有盟友均摊，并且被击退。"}}
D.SpellTexts[187074]={Description={["7f7e0ac20ce91299:48"]="攻击地狱火炮，造成自然伤害。"}}
D.SpellTexts[187077]={Description={["8ce1184bb0da37ae:41"]="从远处扑向一个敌人，使其流血不止。"}}
D.SpellTexts[187089]={Aura={["885cd64898a4bdaf:37"]="降低附近盟友的邪能腐蚀度。"}}
