D.SpellTexts[187177]={Aura={["9b90f63bfac5d238:34"]="女伯爵莉亚德琳正在协助你战斗。"}}
D.SpellTexts[187178]={Description={["5bf61d37dac3b768:27"]="女伯爵莉亚德琳无法协助你。"},Aura={["5bf61d37dac3b768:27"]="女伯爵莉亚德琳无法协助你。"}}
