D.SpellTexts[187196]={Description={["6f1ed22406c7af9d:114"]="先锋阿基里奥受祖霍拉克召唤而来，他的灵魂与召唤者相连——对其造成的任何伤害同样会对祖霍拉克造成伤害，反之亦然。"},Aura={["3ca53526ba6f72c9:43"]="祖霍拉克与先锋阿基里奥共享生命值。"}}
