D.SpellTexts[187627]={Aura={["dd23c1088348bab3:144"]="古怪的谜题会考验你对元素的掌控能力。将所有火元素图腾翻转成为水元素图腾即可获胜。触摸一个图腾就可以将其翻转，同时还会翻转其周围的四个图腾。"}}
