D.SpellTexts[188249]={Description={["708a4d0e81054661:261"]="奥图里斯对族人的传统生活并不怎么放在心上。受难者更喜欢的是和他的虚空幼龙奈瑟兰达姆斯在一起，享受孤身一人投入战斗的刺激。然而他并不愚蠢，也愿意与他人合作，只要合作者能够证明自己同样有着超凡卓群的技艺，可以跟上他的节奏。"}}
