D.SpellTexts[188479]={Description={["48fe6e5e5764419b:195"]="施法者用邪能感染随机影响一名玩家，对受害者造成越来越高的自然伤害，直到玩家将其传染给附近的盟友。当感染转移时，旧的宿主会受到邪能疫病的影响。"}}
