D.SpellTexts[191521]={Description={["900be329769c5796:472"]="达里安·莫格莱尼曾经是一名效力于银色黎明的圣骑士。为了阻止天灾的入侵，他牺牲了自己，然而他的尸体却被巫妖克尔苏加德变成了死亡骑士。作为死亡骑士的他带领着黑锋骑士团向圣光之愿礼拜堂发动了攻击，最终却发现这次攻击只是一次自杀式的任务，目的只是逼出隐藏在暗处的提里奥·弗丁。\r\n得知他和同胞只是被当作炮灰，莫格莱尼在盛怒之下摆脱了巫妖王的控制，并带领黑锋骑士团走上了复仇的道路。"},Aura={["71aa918e38ddd49d:88"]="沉默又极端的莫格莱尼会仔细研究每一名敌人，不择手段地让他们感受到痛苦。"}}
