D.SpellTexts[191731]={Description={["672823f8819a98df:217"]="亡者大军召唤的食尸鬼在使用爪击时会产生额外的效果。\r\n\r\n死亡：提高从死亡骑士处所受到的伤害。\r\n战争：降低造成的治疗效果。\r\n饥荒：降低对死亡骑士造成的伤害。\r\n瘟疫：额外造成持续伤害。"},Aura={["e3e38030e8132ded:147"]="死亡提高来自死亡骑士的伤害。\r\n战争降低造成的治疗效果。\r\n饥荒降低对死亡骑士造成的伤害。\r\n瘟疫造成持续伤害。"}}
