D.SpellTexts[192144]={Description={["12ac7ea8becd52f5:178"]="被萨尔从收容所中解放出来以后，经过多年的战斗与成长，纳兹格雷尔成了部落最忠实、最老练的指挥官。他最近一次执行任务是前往萨尔玛，然而在军团入侵之后，他又返回艾泽拉斯，力图拯救这个世界。"},Aura={["2e561af2fe8b3427:63"]="纳兹格雷尔是一位不苟言笑的战士，有着优秀的战术素养，同时精通多种武器。"}}
D.SpellTexts[192151]={Description={["35da539f91f7d54c:178"]="莱诺尔是一位身经百战的老兵，她参与过打开甲虫之墙的战役，并在诺森德出任第七军团的精英指挥官。战役结束之后，她回到了故乡，协助对抗燃烧军团的威胁。"},Aura={["38800d8f10ec8578:93"]="莱诺尔试图用无情而狂暴的攻击吸引敌人的注意力，保护其他盟友。"}}
D.SpellTexts[192162]={Description={["7fa0443422ea30a7:48"]="右键点击以召唤或解散你的幽灵织网蛛。"}}
