D.SpellTexts[192332]={Description={["1d8b401fa3b8f49a:394"]="在被萨萨里安杀死之后，库尔迪拉被唤醒成为了死亡骑士。虽然他死在萨萨里安手上，但二人之间却一直以朋友相待，直到安多哈尔的战事爆发，二人率领各自阵营的部队在战场上见面了。起初二人一直处于停战状态，然而在希尔瓦娜斯·风行者加入战斗后，库尔迪拉被女妖之王遣回幽暗城。当人们问及此事时，库尔迪拉一直不愿谈及更多的情况。"}}
