D.SpellTexts[192656]={Description={["6b3066e7f438476a:165"]="艾露恩之光照耀着你，使你免疫侵蚀之影的效果，并照出所有暗影庇体的敌人。\r\n\r\n艾露恩之光存在时，你无法进入潜行。"},Aura={["c56fa9859c72c68e:54"]="免疫侵蚀之影。\r\n照出暗影庇体的敌人。"}}
