D.SpellTexts[192985]={Description={["984e0a257e9275e4:109"]="艾萨拉之怒生命值剩余10%时开始强化天气，并召唤大范围的毁灭性风暴。"}}
D.SpellTexts[192986]={Description={["0833794d2d9bbd98:52"]="如果目标被追踪者的印记所标记，则搜索目标的包裹。"}}
