D.SpellTexts[193020]={Description={["55a8a36f851d92c4:36"]="使玩家与抑魔金熔炉调和。"},Aura={["1a65f1812ffbdf92:107"]="与抑魔金熔炉调和，允许你在拆解物品时不需要点击确认。距离熔炉太远会取消该效果。"}}
D.SpellTexts[193023]={Description={["db08cd27a49a0b62:123"]="抑魔金熔炉可以焚化高等级的锻造装备来制造抑魔金。物品将被永久摧毁。\r\n\r\n是否继续？"}}
D.SpellTexts[193024]={Description={["13f49f6db05a9f1e:85"]="焚化高等级锻造装备，制造抑魔金灰烬。目标物品将被摧毁。"}}
D.SpellTexts[193051]={Aura={["ef8f423ce516ab6f:34"]="深须国王召唤大海来协助他！"}}
D.SpellTexts[193059]={Description={["979997f4ce4e183b:8"]=S[13680]},Aura={["979997f4ce4e183b:8"]=S[13680]}}
D.SpellTexts[193069]={Description={["c97033710518c912:151"]="使受害者昏迷，并被梦魇能量感染。当这些能量持续时间结束时，会向四个方向释放，对其经过的所有玩家造成暗影伤害。"}}
D.SpellTexts[193077]={Aura={["13e5b5ad0d726b8e:17"]="正在施加急救。"}}
