D.SpellTexts[193698]={Description={["de767a27228b8fe0:163"]="积怨夫人用奥术魔法诅咒敌人。当诅咒被移除时，携带者会向前方锥形区域释放奥术能量冲击，将所有玩家推走，并摧毁小型生物。"},Aura={["78c57c6b2deb4168:58"]="效果结束后，对前方锥形区域内施放一道奥术能量冲击。"}}
