D.SpellTexts[193754]={Description={["8077af91d020b770:131"]="将施法者传送至圣光秘殿。\r\n\r\n在圣光秘殿施放指引之光将把圣骑士传送回出发点附近。"}}
D.SpellTexts[193755]={Description={["ccd03b3210940e4f:127"]="将施法者传送至艾泽拉斯之心。\r\n\r\n在艾泽拉斯之心再次施放风暴召唤将把施法者传回原先的位置附近。"}}
D.SpellTexts[193756]={Description={["3ecfade8c625351b:57"]="召唤雄鹰之魂，将猎人送至神射手营地。"}}
D.SpellTexts[193757]={Description={["278b286e94d0030d:137"]="萨拉将施法者传送至虚空之光神殿。\r\n\r\n在虚空之光神殿施放光明传送将把牧师传送回出发点附近。"}}
D.SpellTexts[193758]={Description={["c5513f5cf052693f:125"]=S[9923]}}
D.SpellTexts[193759]={Description={["fc3b46f83a00d6fb:35"]="将你传送至守护者圣殿。"}}
D.SpellTexts[193761]={Description={["97409eb46e2d57e3:130"]="将施法者传送至暗影大厅。\r\n\r\n在暗影大厅施放集结点将把潜行者传送回出发点附近。"}}
D.SpellTexts[193763]={Aura={["b8aa92e0f503e989:44"]="无法从阿格拉玛圣坛中获益。"}}
